import{_ as t}from"./chunks/protocol.BCHVaPua.js";import{_ as a,o as i,c as r,a2 as s}from"./chunks/framework.BefGvJmu.js";const v=JSON.parse('{"title":"The PAI protocol","description":"How personal AI applications publish and retrieve content through a PAI service.","frontmatter":{"title":"The PAI protocol","description":"How personal AI applications publish and retrieve content through a PAI service."},"headers":[],"relativePath":"protocol.md","filePath":"protocol.md"}'),o={name:"protocol.md"};function n(c,e,l,d,p,h){return i(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="the-pai-protocol" tabindex="-1">The PAI protocol <a class="header-anchor" href="#the-pai-protocol" aria-label="Permalink to &quot;The PAI protocol&quot;">​</a></h1><p>PAI defines how personal AI applications publish, update, and retrieve content through a service. Its current content profile gives clients a shared way to find operations, upload documents, read published material, and retain source links.</p><h2 id="who-implements-what" tabindex="-1">Who implements what <a class="header-anchor" href="#who-implements-what" aria-label="Permalink to &quot;Who implements what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Participant</th><th>Role</th></tr></thead><tbody><tr><td>Host application</td><td>The tool or Harness in which a person works with their AI. It uses a PAI client.</td></tr><tr><td>PAI client</td><td>Discovers a service and carries out publication or retrieval operations.</td></tr><tr><td>PAI server</td><td>Implements the content interfaces within a service. It validates uploads, checks ownership, and exposes published versions.</td></tr><tr><td>Service provider</td><td>Operates the server and supplies the account system, storage, and product interface.</td></tr></tbody></table><p>The same selected service receives publication requests and serves content to readers. A platform can implement these interfaces alongside its existing services. Follo is one potential provider.</p><p><img src="'+t+'" alt="Publisher and reader clients use the same selected service."></p><h2 id="publish-update-retrieve" tabindex="-1">Publish, update, retrieve <a class="header-anchor" href="#publish-update-retrieve" aria-label="Permalink to &quot;Publish, update, retrieve&quot;">​</a></h2><p>A client starts at <code>/.well-known/pai.json</code>. The service descriptor advertises supported capabilities, accepted file formats, and endpoint URLs.</p><p><strong>Publish.</strong> The client sends a complete <code>.pai</code> or <code>.pai.html</code> file with a publisher credential. The server validates it, stores a publication version, and returns its resource and representation URLs.</p><p><strong>Update.</strong> The owning publisher submits a changed document to the resource&#39;s update URL. A new document revision creates another stored publication version. Repeating the same revision and content returns the existing snapshot.</p><p><strong>Retrieve.</strong> A reader selects a resource from the catalogue or uses a known resource URL. Structured content provides ordered Markdown blocks, image metadata, and source links. The complete file supplies original image bytes when needed.</p><p><a href="/pai-website/spec/service.html">Read the service specification</a> · <a href="/pai-website/guide/architecture.html">View the full architecture</a></p><h2 id="keep-the-source-tied-to-its-version" tabindex="-1">Keep the source tied to its version <a class="header-anchor" href="#keep-the-source-tied-to-its-version" aria-label="Permalink to &quot;Keep the source tied to its version&quot;">​</a></h2><p>Document IDs travel with files. A document revision records content edits. The service assigns its own resource ID and publication version.</p><p>Each returned block has a <code>sourceUrl</code> pointing to its location in a particular published snapshot. A later update preserves that earlier source. Clients can retain document, publication, block, and asset identifiers when reusing material.</p><p>Publication and updates use Bearer credentials. Published content is publicly readable under the current profile. The service determines ownership from the credential.</p><h2 id="build-against-the-current-draft" tabindex="-1">Build against the current draft <a class="header-anchor" href="#build-against-the-current-draft" aria-label="Permalink to &quot;Build against the current draft&quot;">​</a></h2><p>The reference implementation includes publication and retrieval clients, an HTTP server, and a command that checks a service through its advertised interfaces.</p><ul><li><a href="/pai-website/guide/client.html">Client integration</a>: connect an AI application or Harness.</li><li><a href="/pai-website/guide/server.html">Server integration</a>: implement the content profile in a platform.</li><li><a href="/pai-website/spec/">Specification overview</a>: read normative requirements, schemas, and fixed examples.</li></ul><p>The current protocol is <code>0.1.0-draft.1</code>. The specifications are maintained in English; this page is an introduction.</p><h2 id="planned-extensions" tabindex="-1">Planned extensions <a class="header-anchor" href="#planned-extensions" aria-label="Permalink to &quot;Planned extensions&quot;">​</a></h2><p>Query-based retrieval will build on published versions, block identifiers, and source URLs to return relevant material for a request. Hosted-agent work will define how a service operates an outward-facing agent within a user&#39;s authorized scope. Both extensions are planned; their message formats remain to be specified.</p>',22)])])}const b=a(o,[["render",n]]);export{v as __pageData,b as default};
